#!/bin/bash
set -euo pipefail
RUN=/var/lib/kalshi-study/reproduction-btc-20261117
mkdir -p "$RUN"
exec >>"$RUN/provisional.log" 2>&1
trap 'rc=$?; echo "FAIL $rc $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-status.txt"' ERR
export PYTHONPATH=/opt/kalshi SCALE_FREE_STRICT=1 PYTHONWARNINGS=ignore OPENBLAS_NUM_THREADS=1
printf '%s' '' | base64 -d > "$RUN/smoke_features.json"
printf '%s' '' | base64 -d > "$RUN/build_provisional_frame.py"
printf '%s' '' | base64 -d > "$RUN/verify_provisional_frame.py"
printf '%s' '' | base64 -d > "$RUN/provisional_tc.py"
echo "RUNNING assemble $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-status.txt"
/opt/kalshi/venv/bin/python -u "$RUN/build_provisional_frame.py"
echo "RUNNING verify $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-status.txt"
/opt/kalshi/venv/bin/python -u "$RUN/verify_provisional_frame.py"
echo "RUNNING train $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-status.txt"
export TC_COINS=BTC TC_THREADS=4 REPRO_PANELS=/mnt/scratch/reproduction/panels REPRO_OUTPUT_DIR="$RUN/provisional-output"
/opt/kalshi/venv/bin/python -u "$RUN/provisional_tc.py"
echo "RUNNING upload $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-status.txt"
tar -C "$RUN" -czf "$RUN/provisional-artifacts.tgz" provisional_tc.py build_provisional_frame.py verify_provisional_frame.py provisional-output provisional.log
/opt/kalshi/venv/bin/python - <<'PYCODE'
from azure.identity import DefaultAzureCredential
from azure.storage.blob import BlobServiceClient
path='/var/lib/kalshi-study/reproduction-btc-20261117/provisional-artifacts.tgz'
blob=BlobServiceClient('https://kalshiobfdfaed53.blob.core.windows.net',credential=DefaultAzureCredential()).get_blob_client('tape','research/reproductions/btc-tradecheck-20261117/provisional.tgz')
with open(path,'rb') as f:blob.upload_blob(f,overwrite=False)
print("Uploaded provisional artifacts",flush=True)
PYCODE
echo "COMPLETE $(date -u --iso-8601=seconds)" | tee "$RUN/provisional-status.txt"
